<div class="settings-section payment-methods-panel">
  <div class="section-header-row"><div><h2 class="section-subtitle">אמצעי תשלום</h2><p class="hint-text">הוסיפו כרטיסים ואמצעים לבית. נשמרות רק 4 ספרות אחרונות.</p></div><button class="btn-primary" type="button" onclick="openPaymentMethodEditor()"><i class="fa-solid fa-plus"></i> הוספה</button></div>
  <div id="payment-methods-list"></div>
</div>
<div id="payment-method-modal" class="modal"><div class="modal-content" style="max-width:460px"><div class="modal-header"><h3 id="pm-modal-title">אמצעי תשלום חדש</h3><button type="button" class="close-modal-btn" onclick="closePaymentMethodEditor()"><i class="fa-solid fa-xmark"></i></button></div><form id="payment-method-form" class="form-fields-pill"><input type="hidden" name="id" id="pm-id"><div class="input-group"><label>סוג</label><select name="type" id="pm-type" onchange="toggleCardFields()"><option value="bank_transfer">בנק / העברה</option><option value="credit_card">כרטיס אשראי</option><option value="cash">מזומן</option><option value="check">צ'ק</option><option value="bank_debit">הוראת קבע</option></select></div><div class="input-group"><label>שם שיופיע במערכת</label><input name="name" id="pm-name" required placeholder="למשל: אשראי 3403"></div><div id="pm-card-fields" class="credit-card-editor"><i class="fa-solid fa-credit-card"></i><div><label>חברת אשראי / מנפיק</label><input name="issuer" id="pm-issuer" placeholder="למשל: max"></div><div><label>4 ספרות אחרונות</label><input name="last4" id="pm-last4" inputmode="numeric" maxlength="4" pattern="\d{4}" placeholder="3403"></div></div><div id="pm-msg"></div><button class="btn-primary" type="submit">שמירה</button></form></div></div>
<style>.section-header-row{display:flex;justify-content:space-between;align-items:center;gap:16px}.payment-method-card{display:flex;align-items:center;justify-content:space-between;padding:16px;margin:10px 0;border:1px solid #e5e7eb;border-radius:16px;background:#fff}.payment-method-card.inactive{opacity:.55}.pm-icon{width:46px;height:46px;border-radius:14px;background:#eef7ee;color:var(--main);display:grid;place-items:center;font-size:1.2rem}.pm-main{display:flex;align-items:center;gap:12px}.pm-actions{display:flex;gap:7px;flex-wrap:wrap}.pm-badge{font-size:.75rem;background:#dcfce7;color:#166534;border-radius:999px;padding:3px 8px}.credit-card-editor{display:none;background:linear-gradient(135deg,#172554,#2563eb);color:#fff;padding:18px;border-radius:18px;grid-template-columns:auto 1fr;gap:12px}.credit-card-editor input{background:rgba(255,255,255,.95)}</style>
